/// The free-form dictionary every named object carries.
class Metadata {
 public:
    /// Reads an object's metadata. This is the plumbing; ask an object
    /// for its own with `metadata()`.
    explicit Metadata(const SerializableObject &object) : object_(object) {}

    /// Empties an object's metadata.
    ///
    /// C: `otio_metadata_clear`
    void clear();

    /// Returns whether anything sits at a path.
    ///
    /// C: `otio_metadata_contains`
    bool contains(const std::string &path) const;

    /// Reads a boolean from the metadata.
    ///
    /// C: `otio_metadata_get_bool`
    bool get_bool(const std::string &path) const;

    /// Reads a rectangle from the metadata.
    ///
    /// C: `otio_metadata_get_box2d`
    Box2d get_box2d(const std::string &path) const;

    /// What `get_color` answers with.
    struct GetColorResult {
        Color value;
        std::string name;
    };

    /// Reads a colour, and the name that goes with it, from the metadata.
    ///
    /// `out_name` may be absent if the name is not wanted.
    ///
    /// C: `otio_metadata_get_color`
    GetColorResult get_color(const std::string &path) const;

    /// Reads a number from the metadata.
    ///
    /// C: `otio_metadata_get_double`
    double get_double(const std::string &path) const;

    /// Reads a signed integer from the metadata.
    ///
    /// C: `otio_metadata_get_int`
    std::int64_t get_int(const std::string &path) const;

    /// Reads a handle to an OTIO object held in the metadata.
    ///
    /// C: `otio_metadata_get_object`
    SerializableObject get_object(const std::string &path) const;

    /// Reads a time from the metadata.
    ///
    /// C: `otio_metadata_get_rational_time`
    RationalTime get_rational_time(const std::string &path) const;

    /// Reads a string from the metadata.
    ///
    /// C: `otio_metadata_get_string`
    std::string get_string(const std::string &path) const;

    /// Reads a span from the metadata.
    ///
    /// C: `otio_metadata_get_time_range`
    TimeRange get_time_range(const std::string &path) const;

    /// Reads a transform from the metadata.
    ///
    /// C: `otio_metadata_get_time_transform`
    TimeTransform get_time_transform(const std::string &path) const;

    /// Reads an unsigned integer from the metadata.
    ///
    /// C: `otio_metadata_get_uint`
    std::uint64_t get_uint(const std::string &path) const;

    /// Reads a point from the metadata.
    ///
    /// C: `otio_metadata_get_v2d`
    V2d get_v2d(const std::string &path) const;

    /// Returns the key at an index of a dictionary at a path.
    ///
    /// Keys are ordered, so walking the indices walks them the same way twice.
    ///
    /// Where there is nothing to report this answers an empty optional, which
    /// is an answer rather than a failure.
    ///
    /// C: `otio_metadata_key_at`
    std::optional<std::string> key_at(const std::string &path, std::size_t index) const;

    /// Returns what kind of value sits at a path.
    ///
    /// An empty or absent path names the metadata dictionary itself, which is
    /// always `ValueKind::DICTIONARY`.
    ///
    /// Where there is nothing to report this answers an empty optional, which
    /// is an answer rather than a failure.
    ///
    /// C: `otio_metadata_kind`
    std::optional<ValueKind> kind(const std::string &path) const;

    /// Returns how many entries a dictionary or an array at a path holds.
    ///
    /// Where there is nothing to report this answers an empty optional, which
    /// is an answer rather than a failure.
    ///
    /// C: `otio_metadata_len`
    std::optional<std::size_t> len(const std::string &path) const;

    /// Removes whatever sits at a path.
    ///
    /// Removing a key of a dictionary takes the key with it; removing an
    /// element of an array shortens the array.
    ///
    /// Where there was nothing to do this throws an `Error` whose status is
    /// `Status::NO_VALUE`, which is an answer rather than a failure.
    ///
    /// C: `otio_metadata_remove`
    void remove(const std::string &path);

    /// Writes a boolean into the metadata.
    ///
    /// C: `otio_metadata_set_bool`
    void set_bool(const std::string &path, bool value);

    /// Writes a rectangle into the metadata.
    ///
    /// C: `otio_metadata_set_box2d`
    void set_box2d(const std::string &path, const Box2d &value);

    /// Writes a colour into the metadata. `name` may be absent for an unnamed
    /// one.
    ///
    /// C: `otio_metadata_set_color`
    void set_color(const std::string &path, const Color &value, const std::optional<std::string> &name = std::nullopt);

    /// Writes an empty dictionary into the metadata, to be filled through
    /// deeper paths.
    ///
    /// C: `otio_metadata_set_dictionary`
    void set_dictionary(const std::string &path);

    /// Writes a number into the metadata.
    ///
    /// C: `otio_metadata_set_double`
    void set_double(const std::string &path, double value);

    /// Writes a signed integer into the metadata.
    ///
    /// C: `otio_metadata_set_int`
    void set_int(const std::string &path, std::int64_t value);

    /// Writes an absent into the metadata.
    ///
    /// C: `otio_metadata_set_null`
    void set_null(const std::string &path);

    /// Writes a handle to an OTIO object into the metadata.
    ///
    /// The object stays where it is and the metadata names it. Nothing checks
    /// that the handle is live, because a document being built may not hold the
    /// object yet.
    ///
    /// C: `otio_metadata_set_object`
    void set_object(const std::string &path, const SerializableObject &value);

    /// Writes a time into the metadata.
    ///
    /// C: `otio_metadata_set_rational_time`
    void set_rational_time(const std::string &path, const RationalTime &value);

    /// Writes a string into the metadata.
    ///
    /// C: `otio_metadata_set_string`
    void set_string(const std::string &path, const std::string &value);

    /// Writes a span into the metadata.
    ///
    /// C: `otio_metadata_set_time_range`
    void set_time_range(const std::string &path, const TimeRange &value);

    /// Writes a transform into the metadata.
    ///
    /// C: `otio_metadata_set_time_transform`
    void set_time_transform(const std::string &path, const TimeTransform &value);

    /// Writes an unsigned integer into the metadata.
    ///
    /// C: `otio_metadata_set_uint`
    void set_uint(const std::string &path, std::uint64_t value);

    /// Writes a point into the metadata.
    ///
    /// C: `otio_metadata_set_v2d`
    void set_v2d(const std::string &path, const V2d &value);

    /// Writes an array of `len` nulls into the metadata, to be filled by index.
    ///
    /// C: `otio_metadata_set_vector`
    void set_vector(const std::string &path, std::size_t len);

 private:
    SerializableObject object_;
};

